      SUBROUTINE DFOLCC     DERIVATIVE OF FIRST-ORDER TRANSFER MATRIX WITH RESPECT C     TO MAGNET LENGTH FOR QUADRUPOLES AND DIPOLESCC     LIST OF COMMON BLOCKSC      INCLUDE 'ELM5A.CIN'      INCLUDE 'ELM5B.CIN'      INCLUDE 'R.CIN'CC     LOCAL VARIABLESC      REAL  DCS, DSNCC---------------------------------------------------      J = JQUAD      CS = R(J,J)      SN = R(J,J+1)      DCS = - KQ2*SN*LVE      DSN = CS*LVE      RV(J,J) = DCS      RV(J,J+1) = DSN      RV(J+1,J) = - KQ2*DSN      RV(J+1,J+1) = DCS      RETURN      END